CREATE TABLE public.surname_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id), type text NOT NULL CHECK(type IN ('version','legend','document','village')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), summary text NOT NULL CHECK(length(summary) BETWEEN 1 AND 400), source_title text NOT NULL DEFAULT '', source_url text NOT NULL DEFAULT '' CHECK(source_url = '' OR source_url ~ '^https?://'), sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL, origin text NOT NULL DEFAULT 'admin' CHECK(origin IN ('admin','user','ai')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.surname_cards TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.surname_cards TO authenticated;
GRANT ALL ON public.surname_cards TO service_role;
ALTER TABLE public.surname_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY cards_public ON public.surname_cards FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY cards_admin ON public.surname_cards FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.family_details (family_id uuid PRIMARY KEY REFERENCES public.families(id), home_villages text[] NOT NULL DEFAULT '{}', region text NOT NULL DEFAULT '', related_family_ids uuid[] NOT NULL DEFAULT '{}', related_family_names text[] NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.family_details TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.family_details TO authenticated;
GRANT ALL ON public.family_details TO service_role;
ALTER TABLE public.family_details ENABLE ROW LEVEL SECURITY;
CREATE POLICY details_public ON public.family_details FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY details_admin ON public.family_details FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.story_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id), user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, kind text NOT NULL CHECK(kind IN ('share','correction')), text text NOT NULL CHECK(length(text) BETWEEN 1 AND 3000), source_url text NOT NULL DEFAULT '' CHECK(source_url = '' OR source_url ~ '^https?://'), contact_consent boolean NOT NULL DEFAULT false, processing_consent_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.story_submissions TO authenticated;
GRANT ALL ON public.story_submissions TO service_role;
ALTER TABLE public.story_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submissions_owner ON public.story_submissions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY submissions_admin ON public.story_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.story_submission_limits (bucket text PRIMARY KEY, last_submission timestamptz NOT NULL);
GRANT ALL ON public.story_submission_limits TO service_role;
ALTER TABLE public.story_submission_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_story_slot(_bucket text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed boolean; BEGIN INSERT INTO public.story_submission_limits(bucket,last_submission) VALUES(_bucket,clock_timestamp()) ON CONFLICT(bucket) DO UPDATE SET last_submission=excluded.last_submission WHERE story_submission_limits.last_submission <= clock_timestamp()-interval '1 minute' RETURNING true INTO claimed; RETURN coalesce(claimed,false); END $$;
REVOKE ALL ON FUNCTION public.claim_story_slot(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_story_slot(text) TO service_role;
CREATE INDEX cards_family_order ON public.surname_cards(family_id,sort_order);
CREATE INDEX submissions_queue ON public.story_submissions(status,created_at);
CREATE FUNCTION public.touch_story_timestamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER cards_timestamp BEFORE UPDATE ON public.surname_cards FOR EACH ROW EXECUTE FUNCTION public.touch_story_timestamp();
CREATE TRIGGER details_timestamp BEFORE UPDATE ON public.family_details FOR EACH ROW EXECUTE FUNCTION public.touch_story_timestamp();
CREATE TRIGGER submissions_timestamp BEFORE UPDATE ON public.story_submissions FOR EACH ROW EXECUTE FUNCTION public.touch_story_timestamp();